class Order { // racine d'agrégat
    private final OrderId id;
    private final CustomerId customerId;   // référence PAR IDENTITÉ (pas un objet Customer)
    private final List<OrderLine> lines;   // dans la frontière de cohérence
    private OrderStatus status;
    private final List<DomainEvent> events = new ArrayList<>();

    void pay(Money paid) {
        if (status != OrderStatus.PENDING) throw new IllegalStateException();
        if (paid.isLessThan(total())) throw new InsufficientPaymentException();
        this.status = OrderStatus.PAID;      // invariant protégé par la racine
        events.add(new OrderPaid(id, customerId)); // fait métier enregistré
    }
    List<DomainEvent> pullEvents() { var e = List.copyOf(events); events.clear(); return e; }
}
